-- MP-0038: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0038: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0038: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0038: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('cha-kee-chin','aminuddin-harun','mohd-isam-mohd-isa') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0038: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('rasah','port dickson','tampin') and slug not in ('cha-kee-chin','aminuddin-harun','mohd-isam-mohd-isa')) then raise exception 'MP-0038: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0038:%' and (m.source_type <> 'editorial' or e.slug not in ('cha-kee-chin','aminuddin-harun','mohd-isam-mohd-isa') or m.import_key not like 'MP-0038:' || e.slug || ':%')) then raise exception 'MP-0038: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'cha-kee-chin','Cha Kee Chin','government','Member of the Dewan Rakyat','Rasah','Negeri Sembilan','Cha Kee Chin represents Rasah, Negeri Sembilan, in the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4169','/portraits/cha-kee-chin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P130.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4169"}, {"label": "DAP · current Negeri Sembilan representatives", "url": "https://dapmalaysia.org/negeri-sembilan-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'aminuddin-harun','Aminuddin Harun','government','Member of the Dewan Rakyat','Port Dickson','Negeri Sembilan','Aminuddin Harun represents Port Dickson, Negeri Sembilan, in the Dewan Rakyat. A PKR member. Previously served as Menteri Besar of Negeri Sembilan.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4171','/portraits/aminuddin-harun.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/PD.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4171"}, {"label": "PKR · current representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}, {"label": "Former state office · 16 August 2026", "url": "https://bernama.com/radio/news.php?id=2595014"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'mohd-isam-mohd-isa','Mohd Isam Mohd Isa','government','Member of the Dewan Rakyat','Tampin','Negeri Sembilan','Mohd Isam Mohd Isa represents Tampin, Negeri Sembilan, in the Dewan Rakyat. A UMNO member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4172','/portraits/mohd-isam-mohd-isa.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P133.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4172"}, {"label": "UMNO · Tampin division chief, 11 September 2026", "url": "https://umno-online.my/2026/09/11/umno-bukan-stesen-transit-politik-mohd-isam/"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('cha-kee-chin','aminuddin-harun','mohd-isam-mohd-isa') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0038: concurrent ownership or identity change'; end if; end $$;

commit;
